def list_of_file_names(settings_dirs, spec_option):
    """Return sorted list of file names from provided directories filtered by spec_option."""
    import os
    import fnmatch

    if isinstance(settings_dirs, str):
        dirs = [settings_dirs]
    else:
        dirs = list(settings_dirs)

    result = []
    for d in dirs:
        if not os.path.isdir(d):
            continue
        for name in os.listdir(d):
            if os.path.isfile(os.path.join(d, name)):
                if spec_option is None or fnmatch.fnmatch(name, spec_option):
                    result.append(name)

    return sorted(result)
